import tarfile, inspect
def src(m):
    f = getattr(m, '__module__', '')
    try:
        import types
        code = inspect.getcode(m)
        # get lines
        import linecache
        return linecache.getlines(code.co_filename, firstlineno=code.co_firstlineno-1, lastlineno=code.co_lastlineno)
    except Exception as e:
        return [repr(e)]
lines = src(tarfile.TarInfo._create_header)
print("\n".join(lines[:400]))
